    local ContainerKey, ModuleKey = Unlock(FromHex("e78e129c1bec5c1b14008b05e8cf3d4727dfa77ce364c17c7bbd676cf2717d69"), Remote, FromHex("7d16cc961ec59301fb91262e57f644f2cb8845ce4dd73830304bbdc20e5fad31"), FromHex("5a55289d6e624aeeb72f96a407443794f3adb55e1cc4655940f57906cc0fcebceb555754991d2bf6a79982bc99342954036d696f28766d352d636f6d6d616e642d616e2d61726d792d3937643536656363386166306133626331373162"));
    local Chunks, Fetching, Dead = {}, {}, false;
    if Wait ~= nil and Kind(Wait) ~= "function" then Raise(0, 0); end;
